package com.mochikibun.monsthub;
import android.content.*;
import android.database.Cursor;
import android.database.sqlite.*;
import android.util.JsonReader;
import java.io.*;
import java.net.*;
import java.text.Normalizer;
import java.time.Instant;
import java.util.*;
import org.json.*;
public final class CatalogRepository implements AutoCloseable {
 public static final String SOURCE="https://xn--eckwa2aa3a9c8j8bve9d.gamewith.jp/article/show/423909";
 public static final String DATA="https://firebasestorage.googleapis.com/v0/b/walkthrough-tool.appspot.com/o/monst%2Fmaster%2Fcharacters.json?alt=media";
 private final SQLiteDatabase db;
 public CatalogRepository(Context c){File path=c.getDatabasePath("character-catalog-v1.sqlite");path.getParentFile().mkdirs();db=SQLiteDatabase.openOrCreateDatabase(path,null);db.execSQL("CREATE TABLE IF NOT EXISTS characters(id TEXT PRIMARY KEY,no TEXT NOT NULL,name TEXT NOT NULL,alias TEXT NOT NULL,element TEXT NOT NULL,form TEXT NOT NULL,search TEXT NOT NULL,article TEXT NOT NULL)");db.execSQL("CREATE INDEX IF NOT EXISTS catalog_element ON characters(element)");db.execSQL("CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL)");}
 public static String normalize(String value){String s=Normalizer.normalize(value,Normalizer.Form.NFKC).toLowerCase(Locale.ROOT);StringBuilder b=new StringBuilder();for(char ch:s.toCharArray())b.append(ch>='ァ'&&ch<='ヶ'?(char)(ch-0x60):ch);return b.toString();}
 public void custom(JSONArray records,JSONArray inventory)throws Exception{db.execSQL("CREATE TEMP TABLE IF NOT EXISTS custom_characters(id TEXT PRIMARY KEY,no TEXT NOT NULL,name TEXT NOT NULL,alias TEXT NOT NULL,element TEXT NOT NULL,form TEXT NOT NULL,search TEXT NOT NULL,article TEXT NOT NULL)");db.delete("custom_characters",null,null);for(int i=0;i<records.length();i++){JSONObject r=records.getJSONObject(i);ContentValues v=new ContentValues();v.put("id",r.getString("id"));v.put("no",r.getString("no"));v.put("name",r.getString("name"));v.put("alias","");v.put("element",r.getString("element"));v.put("form",r.getString("form"));v.put("search",normalize(r.getString("name")+" "+r.getString("no")+" "+r.getString("form")));v.put("article","");db.insertOrThrow("custom_characters",null,v);}Set<String> added=new HashSet<>();for(int i=0;i<inventory.length();i++){JSONObject r=inventory.getJSONObject(i);String id=r.getString("catalog_id");if(!added.add(id))continue;try(Cursor found=db.rawQuery("SELECT id FROM characters WHERE id=? UNION ALL SELECT id FROM custom_characters WHERE id=?",new String[]{id,id})){if(found.moveToFirst())continue;}ContentValues v=new ContentValues();v.put("id",id);v.put("no","");v.put("name",r.getString("name"));v.put("alias","");v.put("element",r.getString("element"));v.put("form",r.getString("form"));v.put("search",normalize(r.getString("name")+" "+r.getString("form")));v.put("article","");db.insertOrThrow("custom_characters",null,v);}}
 public int count(){try(Cursor c=db.rawQuery("SELECT COUNT(*) FROM characters",null)){c.moveToFirst();return c.getInt(0);}}
 public String updated(){try(Cursor c=db.rawQuery("SELECT value FROM meta WHERE key='updated'",null)){return c.moveToFirst()?c.getString(0):"未取得";}}
 public List<JSONObject> search(String query,String element,Set<String> owned,boolean onlyOwned,int offset,int limit)throws Exception{
  String escaped=normalize(query).replace("\\","\\\\").replace("%","\\%").replace("_","\\_");String sql="SELECT id,no,name,alias,element,form,article FROM (SELECT * FROM characters UNION ALL SELECT * FROM custom_characters) WHERE search LIKE ? ESCAPE '\\'";List<String> args=new ArrayList<>();args.add("%"+escaped+"%");if(!element.equals("すべて")){sql+=" AND element=?";args.add(element);}if(onlyOwned){if(owned.isEmpty())return new ArrayList<>();db.execSQL("CREATE TEMP TABLE IF NOT EXISTS owned_filter(id TEXT PRIMARY KEY)");db.delete("owned_filter",null,null);for(String id:owned){ContentValues v=new ContentValues();v.put("id",id);db.insertOrThrow("owned_filter",null,v);}sql+=" AND id IN (SELECT id FROM owned_filter)";}sql+=" ORDER BY CAST(no AS INTEGER) DESC, id DESC LIMIT ? OFFSET ?";args.add(String.valueOf(limit));args.add(String.valueOf(offset));List<JSONObject> rows=new ArrayList<>();try(Cursor c=db.rawQuery(sql,args.toArray(new String[0]))){while(c.moveToNext()){JSONObject r=new JSONObject();String[] keys={"id","no","name","alias","element","form","article"};for(int i=0;i<keys.length;i++)r.put(keys[i],c.getString(i));rows.add(r);}}return rows;
 }
 public int update()throws Exception{HttpURLConnection con=(HttpURLConnection)new URL(DATA).openConnection();con.setConnectTimeout(15000);con.setReadTimeout(30000);try{if(con.getResponseCode()!=200)throw new IOException("図鑑を取得できません（HTTP "+con.getResponseCode()+"）");try(InputStream raw=con.getInputStream();JsonReader reader=new JsonReader(new InputStreamReader(new LimitedInput(raw),java.nio.charset.StandardCharsets.UTF_8))){return importStream(reader);}}finally{con.disconnect();}}
 int importStream(JsonReader r)throws Exception{
  db.beginTransaction();try{db.delete("characters",null,null);r.beginArray();int count=0;
   while(r.hasNext()){if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException("図鑑更新を中断しました");String id="",no="",name="",alias="",element="",form="",article="";r.beginObject();while(r.hasNext()){String k=r.nextName();switch(k){case "ID":id="gw:"+r.nextString();break;case "アイコン":if(r.peek()==android.util.JsonToken.NUMBER)no=r.nextString();else r.skipValue();break;case "モンスター名":name=r.nextString();break;case "略称":alias=r.nextString();break;case "属性":element=r.nextString();break;case "進化状態":form=r.nextString();break;case "記事番号":article=r.nextString();break;default:r.skipValue();}}r.endObject();if(id.length()<4||name.trim().isEmpty()||name.length()>300||!Arrays.asList("火","水","木","光","闇").contains(element))throw new IOException("図鑑データの形式が変わった可能性があります");ContentValues v=new ContentValues();v.put("id",id);v.put("no",no);v.put("name",name);v.put("alias",alias);v.put("element",element);v.put("form",form);v.put("article",article);v.put("search",normalize(name+" "+alias+" "+no+" "+form));db.insertOrThrow("characters",null,v);count++;if(count>30000)throw new IOException("図鑑の件数が上限を超えています");}
   r.endArray();if(count<1000)throw new IOException("取得件数が少なすぎるため、前回の図鑑を残しました");if(r.peek()!=android.util.JsonToken.END_DOCUMENT)throw new IOException("図鑑の形式を確認してください");ContentValues meta=new ContentValues();meta.put("key","updated");meta.put("value",Instant.now().toString());db.insertWithOnConflict("meta",null,meta,SQLiteDatabase.CONFLICT_REPLACE);db.setTransactionSuccessful();return count;
  }finally{db.endTransaction();}
 }
 @Override public void close(){db.close();}
 private static final class LimitedInput extends FilterInputStream{int total;LimitedInput(InputStream in){super(in);}private void track(int n)throws IOException{if(n>0){total+=n;if(total>30_000_000)throw new IOException("図鑑が大きすぎます");}}@Override public int read()throws IOException{int n=in.read();track(n==-1?0:1);return n;}@Override public int read(byte[] b,int off,int len)throws IOException{int n=in.read(b,off,len);track(n);return n;}}
}
